/**
 * Storage download interpolates object paths into a URL under service credentials.
 * Validate the raw owner boundary before URL normalization or provider dispatch.
 * Uploads generated by this application never contain percent escapes or URL
 * delimiters; ambiguous legacy names require operator review instead.
 */
export function isSafeOwnerStoragePath(path, expectedOwner) {
  const [owner, ...segments] = path.split('/');
  if (
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(owner ?? '') ||
    (expectedOwner !== undefined && owner !== expectedOwner) ||
    segments.length === 0 ||
    segments.some((segment) => segment === '' || segment === '.' || segment === '..') ||
    /[%?#\\\p{Cc}]/u.test(path) ||
    Buffer.byteLength(path, 'utf8') > 1024
  )
    return false;
  try {
    const canonical = new URL(path, 'https://storage-path.invalid/');
    return (
      canonical.origin === 'https://storage-path.invalid' &&
      !canonical.search &&
      !canonical.hash &&
      decodeURIComponent(canonical.pathname.slice(1)) === path
    );
  } catch {
    return false;
  }
}
